 1→import { createContext, useContext, useState, useEffect, type ReactNode } from 'react';
 2→
 3→type Theme = 'light' | 'dark';
 4→
 5→interface ThemeContextValue {
 6→  theme: Theme;
 7→  toggleTheme: () => void;
 8→}
 9→
10→const ThemeContext = createContext<ThemeContextValue | null>(null);
11→
12→function getInitialTheme(): Theme {
13→  const stored = localStorage.getItem('theme');
14→  if (stored === 'dark' || stored === 'light') return stored;
15→  if (window.matchMedia('(prefers-color-scheme: dark)').matches) return 'dark';
16→  return 'light';
17→}
18→
19→export function ThemeProvider({ children }: { children: ReactNode }) {
20→  const [theme, setTheme] = useState<Theme>(getInitialTheme);
21→
22→  useEffect(() => {
23→    document.documentElement.setAttribute('data-theme', theme);
24→    localStorage.setItem('theme', theme);
25→  }, [theme]);
26→
27→  const toggleTheme = () => setTheme((prev) => (prev === 'dark' ? 'light' : 'dark'));
28→
29→  return (
30→    <ThemeContext.Provider value={{ theme, toggleTheme }}>
31→      {children}
32→    </ThemeContext.Provider>
33→  );
34→}
35→
36→export function useTheme() {
37→  const ctx = useContext(ThemeContext);
38→  if (!ctx) throw new Error('useTheme must be used within ThemeProvider');
39→  return ctx;
40→}
