  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider, useTheme } from './ThemeContext';
  3→import { AgentProvider } from './AgentContext';
  4→import { FileUpload } from './components/FileUpload';
  5→import { QueryEditor } from './components/QueryEditor';
  6→import { ResultsTable } from './components/ResultsTable';
  7→import { ResultMarkdown } from './components/ResultMarkdown';
  8→import { Sidebar } from './components/Sidebar';
  9→import { ErrorMessage } from './components/ErrorMessage';
 10→import { AgentPanel } from './components/AgentPanel';
 11→import type { TableInfo, QueryResult, LangfuseStatus } from './types';
 12→import './App.css';
 13→
 14→function AppContent({ tables, refreshTables, langfuseStatus }: { tables: TableInfo[]; refreshTables: () => Promise<void>; langfuseStatus: LangfuseStatus }) {
 15→  const { theme, toggleTheme } = useTheme();
 16→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 17→  const [error, setError] = useState<string | null>(null);
 18→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 19→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 20→  );
 21→  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
 22→  const [agentOpen, setAgentOpen] = useState(false);
 23→
 24→  const handleAgentToggle = () => {
 25→    setAgentOpen((prev) => !prev);
 26→  };
 27→
 28→  const handleLoadSample = useCallback(async () => {
 29→    setError(null);
 30→    try {
 31→      const response = await fetch('/api/upload/sample', { method: 'POST' });
 32→      if (!response.ok) throw new Error('Failed to load sample dataset');
 33→      await refreshTables();
 34→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 35→    } catch (e) {
 36→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 37→    }
 38→  }, [refreshTables]);
 39→
 40→  const handleFileUpload = useCallback(
 41→    async (file: File) => {
 42→      setError(null);
 43→      try {
 44→        const formData = new FormData();
 45→        formData.append('file', file);
 46→        const response = await fetch('/api/upload', {
 47→          method: 'POST',
 48→          body: formData,
 49→        });
 50→        if (!response.ok) throw new Error('Failed to upload file');
 51→        const result = await response.json();
 52→        await refreshTables();
 53→        setEditorQuery(`SELECT * FROM "${result.name}" LIMIT 100`);
 54→      } catch (e) {
 55→        setError(e instanceof Error ? e.message : 'Failed to upload file');
 56→      }
 57→    },
 58→    [refreshTables]
 59→  );
 60→
 61→  const handleQueryExecute = useCallback(
 62→    async (sql: string) => {
 63→      setError(null);
 64→      setQueryResult(null);
 65→      try {
 66→        const start = performance.now();
 67→        const response = await fetch('/api/query', {
 68→          method: 'POST',
 69→          headers: { 'Content-Type': 'application/json' },
 70→          body: JSON.stringify({ sql }),
 71→        });
 72→        const elapsed = performance.now() - start;
 73→
 74→        if (!response.ok) {
 75→          const errorData = await response.json();
 76→          throw new Error(errorData.detail || 'Query execution failed');
 77→        }
 78→
 79→        const result = await response.json();
 80→        setQueryResult({
 81→          columns: result.columns,
 82→          rows: result.rows,
 83→          rowCount: result.rowCount,
 84→          executionTimeMs: elapsed,
 85→          resultType: result.resultType,
 86→        });
 87→        await refreshTables();
 88→      } catch (e) {
 89→        setError(e instanceof Error ? e.message : 'Query execution failed');
 90→      }
 91→    },
 92→    [refreshTables]
 93→  );
 94→
 95→  const handleTableClick = useCallback((tableName: string) => {
 96→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
 97→  }, []);
 98→
 99→  const handleTableDelete = useCallback(async (tableName: string) => {
100→    if (!confirm(`Delete table "${tableName}"?`)) return;
101→    try {
102→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
103→        method: 'DELETE',
104→      });
105→      if (!response.ok) throw new Error('Failed to delete table');
106→      await refreshTables();
107→    } catch (e) {
108→      setError(e instanceof Error ? e.message : 'Failed to delete table');
109→    }
110→  }, [refreshTables]);
111→
112→  const appClass = [
113→    'app',
114→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
115→  ].filter(Boolean).join(' ');
116→
117→  const themeIcon = theme === 'dark' ? (
118→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
119→      <circle cx="12" cy="12" r="5" />
120→      <line x1="12" y1="1" x2="12" y2="3" />
121→      <line x1="12" y1="21" x2="12" y2="23" />
122→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
123→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
124→      <line x1="1" y1="12" x2="3" y2="12" />
125→      <line x1="21" y1="12" x2="23" y2="12" />
126→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
127→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
128→    </svg>
129→  ) : (
130→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
131→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
132→    </svg>
133→  );
134→
135→  return (
136→    <div className={appClass}>
137→      <div className="app__sidebar-wrapper">
138→        <Sidebar tables={tables} onTableClick={handleTableClick} onTableDelete={handleTableDelete} collapsed={sidebarCollapsed} onToggle={() => setSidebarCollapsed((prev) => !prev)} />
139→      </div>
140→      {agentOpen ? (
141→        <div className="app__agent-wrapper">
142→          <div className="app__header">
143→            <h1 className="app__title">DuckDB Data Agent</h1>
144→            <div className="app__header-actions">
145→              <button
146→                className="app__theme-toggle"
147→                onClick={toggleTheme}
148→                aria-label={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
149→                title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
150→              >
151→                {themeIcon}
152→              </button>
153→              <button
154→                className="app__agent-toggle app__agent-toggle--active"
155→                onClick={handleAgentToggle}
156→              >
157→                Editor Mode
158→              </button>
159→            </div>
160→          </div>
161→          <AgentPanel langfuseStatus={langfuseStatus} />
162→        </div>
163→      ) : (
164→        <div className="app__editor-wrapper">
165→          <div className="app__header">
166→            <h1 className="app__title">DuckDB Data Agent</h1>
167→            <div className="app__header-actions">
168→              <button
169→                className="app__theme-toggle"
170→                onClick={toggleTheme}
171→                aria-label={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
172→                title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
173→              >
174→                {themeIcon}
175→              </button>
176→              <button
177→                className="app__agent-toggle"
178→                onClick={handleAgentToggle}
179→              >
180→                Agent Mode
181→              </button>
182→            </div>
183→          </div>
184→          <div className="app__mode-header">
185→            <span className="app__mode-title">Editor Mode</span>
186→          </div>
187→          <main className="app__main">
188→            <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
189→            <QueryEditor
190→              onExecute={handleQueryExecute}
191→              initialQuery={editorQuery}
192→            />
193→            {error && (
194→              <ErrorMessage message={error} onDismiss={() => setError(null)} />
195→            )}
196→            {queryResult?.resultType === 'markdown' ? (
197→              <ResultMarkdown result={queryResult} />
198→            ) : (
199→              <ResultsTable result={queryResult} />
200→            )}
201→          </main>
202→        </div>
203→      )}
204→    </div>
205→  );
206→}
207→
208→export default function App() {
209→  const [tables, setTables] = useState<TableInfo[]>([]);
210→  const [loading, setLoading] = useState(true);
211→  const [error, setError] = useState<string | null>(null);
212→  const [langfuseStatus, setLangfuseStatus] = useState<LangfuseStatus>({ enabled: false, dashboardUrl: null });
213→
214→  const refreshTables = useCallback(async () => {
215→    try {
216→      const response = await fetch('/api/tables');
217→      if (!response.ok) throw new Error('Failed to fetch tables');
218→      const data = await response.json();
219→      setTables(data);
220→    } catch (e) {
221→      console.error('Failed to refresh tables:', e);
222→    }
223→  }, []);
224→
225→  useEffect(() => {
226→    (async () => {
227→      try {
228→        const response = await fetch('/api/health');
229→        if (!response.ok) throw new Error('Backend is not available');
230→        await refreshTables();
231→        try {
232→          const lfRes = await fetch('/api/langfuse/status');
233→          if (lfRes.ok) {
234→            setLangfuseStatus(await lfRes.json());
235→          }
236→        } catch {
237→          // Langfuse status fetch is non-critical
238→        }
239→      } catch (e) {
240→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
241→      } finally {
242→        setLoading(false);
243→      }
244→    })();
245→  }, [refreshTables]);
246→
247→  if (loading) {
248→    return <div className="app-loading">Connecting to backend...</div>;
249→  }
250→
251→  if (error) {
252→    return (
253→      <div className="app-error">Failed to connect: {error}</div>
254→    );
255→  }
256→
257→  return (
258→    <ThemeProvider>
259→      <AgentProvider refreshTables={refreshTables}>
260→        <AppContent tables={tables} refreshTables={refreshTables} langfuseStatus={langfuseStatus} />
261→      </AgentProvider>
262→    </ThemeProvider>
263→  );
264→}
