  1→import { useCallback, useRef, useState, type DragEvent } from 'react';
  2→import './FileUpload.css';
  3→
  4→interface FileUploadProps {
  5→  onUpload: (file: File) => Promise<void>;
  6→  onLoadSample: () => Promise<void>;
  7→}
  8→
  9→const MAX_SIZE_BYTES = 500 * 1024 * 1024; // 500MB
 10→
 11→export function FileUpload({ onUpload, onLoadSample }: FileUploadProps) {
 12→  const [dragging, setDragging] = useState(false);
 13→  const [uploading, setUploading] = useState(false);
 14→  const [loadingSample, setLoadingSample] = useState(false);
 15→  const inputRef = useRef<HTMLInputElement>(null);
 16→
 17→  const handleFile = useCallback(async (file: File) => {
 18→    if (!file.name.toLowerCase().endsWith('.csv')) {
 19→      alert('Only .csv files are supported.');
 20→      return;
 21→    }
 22→    if (file.size > MAX_SIZE_BYTES) {
 23→      alert('File exceeds 500MB limit.');
 24→      return;
 25→    }
 26→    setUploading(true);
 27→    try {
 28→      await onUpload(file);
 29→    } finally {
 30→      setUploading(false);
 31→    }
 32→  }, [onUpload]);
 33→
 34→  const handleLoadSample = useCallback(async () => {
 35→    setLoadingSample(true);
 36→    try {
 37→      await onLoadSample();
 38→    } finally {
 39→      setLoadingSample(false);
 40→    }
 41→  }, [onLoadSample]);
 42→
 43→  const onDrop = useCallback((e: DragEvent) => {
 44→    e.preventDefault();
 45→    setDragging(false);
 46→    const file = e.dataTransfer.files[0];
 47→    if (file) handleFile(file);
 48→  }, [handleFile]);
 49→
 50→  const onDragOver = useCallback((e: DragEvent) => {
 51→    e.preventDefault();
 52→    setDragging(true);
 53→  }, []);
 54→
 55→  const onDragLeave = useCallback(() => {
 56→    setDragging(false);
 57→  }, []);
 58→
 59→  return (
 60→    <div className="file-upload-wrapper">
 61→      <div
 62→        className={`file-upload ${dragging ? 'file-upload--dragging' : ''}`}
 63→        onDrop={onDrop}
 64→        onDragOver={onDragOver}
 65→        onDragLeave={onDragLeave}
 66→        onClick={() => inputRef.current?.click()}
 67→      >
 68→        <input
 69→          ref={inputRef}
 70→          type="file"
 71→          accept=".csv"
 72→          className="file-upload__input"
 73→          onChange={(e) => {
 74→            const file = e.target.files?.[0];
 75→            if (file) handleFile(file);
 76→            e.target.value = '';
 77→          }}
 78→        />
 79→        {uploading ? (
 80→          <p className="file-upload__text">Uploading...</p>
 81→        ) : (
 82→          <p className="file-upload__text">
 83→            Drop a CSV file here or click to browse
 84→          </p>
 85→        )}
 86→      </div>
 87→      <div className="file-upload-divider">
 88→        <span>or</span>
 89→      </div>
 90→      <button
 91→        className="file-upload-sample-btn"
 92→        onClick={handleLoadSample}
 93→        disabled={loadingSample}
 94→      >
 95→        {loadingSample ? 'Loading...' : 'Load Sample Dataset (Titanic)'}
 96→      </button>
 97→    </div>
 98→  );
 99→}
