 1→import { useState, useCallback, type KeyboardEvent } from 'react';
 2→import './QueryEditor.css';
 3→
 4→interface QueryEditorProps {
 5→  onExecute: (sql: string) => Promise<void>;
 6→  initialQuery?: string;
 7→}
 8→
 9→export function QueryEditor({ onExecute, initialQuery }: QueryEditorProps) {
10→  const [sql, setSql] = useState(initialQuery ?? '');
11→  const [running, setRunning] = useState(false);
12→
13→  // Update when parent changes initialQuery
14→  const [prevInitial, setPrevInitial] = useState(initialQuery);
15→  if (initialQuery !== prevInitial) {
16→    setPrevInitial(initialQuery);
17→    if (initialQuery !== undefined) setSql(initialQuery);
18→  }
19→
20→  const run = useCallback(async () => {
21→    const trimmed = sql.trim();
22→    if (!trimmed || running) return;
23→    setRunning(true);
24→    try {
25→      await onExecute(trimmed);
26→    } finally {
27→      setRunning(false);
28→    }
29→  }, [sql, running, onExecute]);
30→
31→  const onKeyDown = useCallback(
32→    (e: KeyboardEvent) => {
33→      if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
34→        e.preventDefault();
35→        run();
36→      }
37→    },
38→    [run]
39→  );
40→
41→  return (
42→    <div className="query-editor">
43→      <textarea
44→        className="query-editor__textarea"
45→        value={sql}
46→        onChange={(e) => setSql(e.target.value)}
47→        onKeyDown={onKeyDown}
48→        placeholder="Enter SQL query... (Ctrl+Enter to run)"
49→        rows={6}
50→        spellCheck={false}
51→      />
52→      <div className="query-editor__actions">
53→        <button
54→          className="query-editor__run-btn"
55→          onClick={run}
56→          disabled={running || !sql.trim()}
57→        >
58→          {running ? 'Running...' : 'Run Query'}
59→        </button>
60→      </div>
61→    </div>
62→  );
63→}
