 76→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
 77→  const { isStreaming, editMessage, deleteMessage } = useAgent();
 78→  const [isEditing, setIsEditing] = useState(false);
 79→  const [editText, setEditText] = useState(message.content);
 80→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
 81→  const textareaRef = useRef<HTMLTextAreaElement>(null);
 82→
 83→  const isUser = message.role === 'user';
 84→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
 85→
 86→  useEffect(() => {
 87→    if (isEditing && textareaRef.current) {
 88→      textareaRef.current.focus();
 89→      textareaRef.current.selectionStart = textareaRef.current.value.length;
 90→    }
 91→  }, [isEditing]);
 92→
 93→  const handleEdit = () => {
 94→    setEditText(message.content);
 95→    setIsEditing(true);
 96→    setIsConfirmingDelete(false);
 97→  };
 98→
 99→  const handleCancelEdit = () => {
100→    setIsEditing(false);
101→    setEditText(message.content);
102→  };
103→
104→  const handleSaveEdit = () => {
105→    const trimmed = editText.trim();
106→    if (!trimmed || trimmed === message.content) {
107→      handleCancelEdit();
108→      return;
109→    }
110→    setIsEditing(false);
111→    editMessage(messageIndex, trimmed);
112→  };
113→
114→  const handleDeleteConfirm = () => {
115→    setIsConfirmingDelete(false);
116→    deleteMessage(messageIndex);
117→  };
118→
119→  const handleKeyDown = (e: React.KeyboardEvent) => {
120→    if (e.key === 'Escape') {
121→      handleCancelEdit();
122→    } else if (e.key === 'Enter' && !e.shiftKey) {
123→      e.preventDefault();
124→      handleSaveEdit();
125→    }
126→  };
127→
128→  let streamingRemainder: string | undefined;
129→  if (hasSegments && message.isStreaming && message.content) {
130→    const segmentedText = message.segments!
131→      .filter((s) => s.type !== 'tool')
132→      .map((s) => s.text || '')
133→      .join('');
134→    const remaining = message.content.slice(segmentedText.length);
135→    if (remaining.trim()) {
136→      streamingRemainder = remaining;
137→    }
138→  }
139→
140→  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
141→  const isInAnswerPhase = message.currentPhase === 'answer';
142→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
143→
144→  const answerSegments = hasSegments
145→    ? message.segments!.filter((s) => s.type === 'answer' && s.text?.trim())
146→    : [];
147→
148→  return (
149→    <div className={`message-bubble message-bubble--${message.role}`}>
150→      <div className="message-bubble__header">
151→        {isUser ? 'You' : 'Assistant'}
152→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
153→          <span className="message-bubble__actions">
154→            <button
155→              className="message-bubble__action-btn"
156→              onClick={handleEdit}
157→              title="Edit message"
158→            >
159→              &#9998;
160→            </button>
161→            <button
162→              className="message-bubble__action-btn message-bubble__action-btn--delete"
163→              onClick={() => setIsConfirmingDelete(true)}
164→              title="Delete message"
165→            >
166→              &#128465;
167→            </button>
168→          </span>
169→        )}
170→      </div>
171→
172→      {isUser && isConfirmingDelete && (
173→        <div className="message-bubble__confirm-delete">
174→          <span>Delete this and all following messages?</span>
175→          <div className="message-bubble__confirm-actions">
176→            <button
177→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
178→              onClick={handleDeleteConfirm}
179→            >
180→              Delete
181→            </button>
182→            <button
183→              className="message-bubble__confirm-btn"
184→              onClick={() => setIsConfirmingDelete(false)}
185→            >
186→              Cancel
187→            </button>
188→          </div>
189→        </div>
190→      )}
191→
192→      {isUser && isEditing ? (
193→        <div className="message-bubble__edit-mode">
194→          <textarea
195→            ref={textareaRef}
196→            className="message-bubble__edit-textarea"
197→            value={editText}
198→            onChange={(e) => setEditText(e.target.value)}
199→            onKeyDown={handleKeyDown}
200→            rows={3}
201→          />
202→          <div className="message-bubble__edit-actions">
203→            <button
204→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
205→              onClick={handleSaveEdit}
206→            >
207→              Save &amp; Resend
208→            </button>
209→            <button
210→              className="message-bubble__edit-btn"
211→              onClick={handleCancelEdit}
212→            >
213→              Cancel
214→            </button>
215→          </div>
216→        </div>
217→      ) : hasSegments ? (
218→        <div className="message-bubble__segments">
219→          <ThinkingBlock
220→            segments={message.segments!}
221→            streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
222→            isActivelyStreaming={isThinkingPhase}
223→          />
224→          {answerSegments.map((seg, i) => (
225→            <div key={i} className="message-bubble__segment message-bubble__segment--answer">
226→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">Answer</div>
227→              <div className="message-bubble__segment-content">
228→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
229→              </div>
230→            </div>
231→          ))}
232→          {isInAnswerPhase && !hasAnswer && streamingRemainder?.trim() && (
233→            <div className="message-bubble__segment message-bubble__segment--answer">
234→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">Answer</div>
235→              <div className="message-bubble__segment-content">
236→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
237→              </div>
238→            </div>
239→          )}
240→          {message.isStreaming && !message.content && (
241→            <span className="message-bubble__typing">Thinking...</span>
242→          )}
243→        </div>
244→      ) : (
245→        <>
246→          <div className="message-bubble__content">
247→            {message.content ? (
248→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
249→            ) : message.isStreaming ? (
250→              <span className="message-bubble__typing">Thinking...</span>
251→            ) : null}
252→          </div>
253→          {message.toolCalls && message.toolCalls.length > 0 && (
254→            <div className="message-bubble__tools">
255→              {message.toolCalls.map((tc) => (
256→                <InlineQueryResult key={tc.toolCallId} result={tc} />
257→              ))}
258→            </div>
259→          )}
260→        </>
261→      )}
262→    </div>
263→  );
264→}
