  1→import { useState, useMemo, useRef, useEffect } from 'react';
  2→import type { QueryResult } from '../types';
  3→import './ResultsTable.css';
  4→
  5→interface ResultsTableProps {
  6→  result: QueryResult | null;
  7→}
  8→
  9→const DISPLAY_CAP = 1000;
 10→
 11→interface SortConfig {
 12→  column: string | null;
 13→  direction: 'asc' | 'desc';
 14→}
 15→
 16→export function ResultsTable({ result }: ResultsTableProps) {
 17→  const [sortConfig, setSortConfig] = useState<SortConfig>({ column: null, direction: 'asc' });
 18→  const [columnFilters, setColumnFilters] = useState<Record<string, string>>({});
 19→  const [globalFilter, setGlobalFilter] = useState('');
 20→  const prevResult = useRef<QueryResult | null>(null);
 21→
 22→  useEffect(() => {
 23→    if (result !== prevResult.current) {
 24→      prevResult.current = result;
 25→      setSortConfig({ column: null, direction: 'asc' });
 26→      setColumnFilters({});
 27→      setGlobalFilter('');
 28→    }
 29→  }, [result]);
 30→
 31→  const filteredRows = useMemo(() => {
 32→    if (!result) return [];
 33→    let rows = result.rows;
 34→
 35→    if (globalFilter) {
 36→      const term = globalFilter.toLowerCase();
 37→      rows = rows.filter((row) =>
 38→        result.columns.some((col) => formatCell(row[col]).toLowerCase().includes(term))
 39→      );
 40→    }
 41→
 42→    const activeFilters = Object.entries(columnFilters).filter(([, v]) => v);
 43→    if (activeFilters.length > 0) {
 44→      rows = rows.filter((row) =>
 45→        activeFilters.every(([col, term]) =>
 46→          formatCell(row[col]).toLowerCase().includes(term.toLowerCase())
 47→        )
 48→      );
 49→    }
 50→
 51→    return rows;
 52→  }, [result, globalFilter, columnFilters]);
 53→
 54→  const sortedRows = useMemo(() => {
 55→    if (!sortConfig.column) return filteredRows;
 56→    const col = sortConfig.column;
 57→    const dir = sortConfig.direction === 'asc' ? 1 : -1;
 58→
 59→    return [...filteredRows].sort((a, b) => {
 60→      const aVal = a[col];
 61→      const bVal = b[col];
 62→
 63→      if (aVal === null || aVal === undefined) return 1;
 64→      if (bVal === null || bVal === undefined) return -1;
 65→
 66→      const aNum = Number(aVal);
 67→      const bNum = Number(bVal);
 68→      if (!isNaN(aNum) && !isNaN(bNum)) return (aNum - bNum) * dir;
 69→
 70→      return String(aVal).localeCompare(String(bVal)) * dir;
 71→    });
 72→  }, [filteredRows, sortConfig]);
 73→
 74→  if (!result) return null;
 75→
 76→  const isFiltered = globalFilter || Object.values(columnFilters).some(Boolean);
 77→  const displayRows = sortedRows.slice(0, DISPLAY_CAP);
 78→  const truncated = sortedRows.length > DISPLAY_CAP;
 79→
 80→  function handleSort(col: string) {
 81→    setSortConfig((prev) => {
 82→      if (prev.column !== col) return { column: col, direction: 'asc' };
 83→      if (prev.direction === 'asc') return { column: col, direction: 'desc' };
 84→      return { column: null, direction: 'asc' };
 85→    });
 86→  }
 87→
 88→  function handleColumnFilter(col: string, value: string) {
 89→    setColumnFilters((prev) => ({ ...prev, [col]: value }));
 90→  }
 91→
 92→  function getSortIcon(col: string) {
 93→    if (sortConfig.column !== col) return ' ↕';
 94→    return sortConfig.direction === 'asc' ? ' ↑' : ' ↓';
 95→  }
 96→
 97→  return (
 98→    <div className="results-table">
 99→      <div className="results-table__toolbar">
100→        <input
101→          className="results-table__global-search"
102→          type="text"
103→          placeholder="Search all columns…"
104→          value={globalFilter}
105→          onChange={(e) => setGlobalFilter(e.target.value)}
106→        />
107→      </div>
108→      <div className="results-table__summary">
109→        {isFiltered
110→          ? `${sortedRows.length} of ${result.rowCount} rows`
111→          : `${result.rowCount} row${result.rowCount !== 1 ? 's' : ''}`}{' '}
112→        in {result.executionTimeMs.toFixed(1)} ms
113→        {truncated && ` (showing first ${DISPLAY_CAP})`}
114→      </div>
115→      {result.columns.length > 0 && (
116→        <div className="results-table__scroll">
117→          <table className="results-table__table">
118→            <thead>
119→              <tr>
120→                {result.columns.map((col) => (
121→                  <th key={col}>
122→                    <button
123→                      className="results-table__col-header"
124→                      onClick={() => handleSort(col)}
125→                    >
126→                      {col}
127→                      <span
128→                        className={`results-table__sort-icon${sortConfig.column === col ? ' results-table__sort-icon--active' : ''}`}
129→                      >
130→                        {getSortIcon(col)}
131→                      </span>
132→                    </button>
133→                    <input
134→                      className="results-table__col-filter"
135→                      type="text"
136→                      placeholder="Filter…"
137→                      value={columnFilters[col] || ''}
138→                      onChange={(e) => handleColumnFilter(col, e.target.value)}
139→                    />
140→                  </th>
141→                ))}
142→              </tr>
143→            </thead>
144→            <tbody>
145→              {displayRows.map((row, i) => (
146→                <tr key={i}>
147→                  {result.columns.map((col) => (
148→                    <td key={col}>{formatCell(row[col])}</td>
149→                  ))}
150→                </tr>
151→              ))}
152→            </tbody>
153→          </table>
154→        </div>
155→      )}
156→    </div>
157→  );
158→}
159→
160→function formatCell(value: unknown): string {
161→  if (value === null || value === undefined) return 'NULL';
162→  if (typeof value === 'object') return JSON.stringify(value);
163→  return String(value);
164→}
